// std::optional<std::string>
template <> struct OOTypeEncoding<std::optional<std::string>> { static constexpr char value[] = 
		"{optional<std::basic_string<char>>={_Optional_payload<std::basic_string<char>, false, false, false>="
		"(_Storage<std::basic_string<char>, false>={_Empty_byte=}{basic_string<char, std::char_traits<char>, "
		"std::allocator<char>>={_Alloc_hider=*}Q(?=[16c]Q)})B}}"; };
// std::vector<oo::EntityHold> *
template <> struct OOTypeEncoding<std::vector<oo::EntityHold> *> { static constexpr char value[] = 
		"^{vector<oo::EntityHold, std::allocator<oo::EntityHold>>={_Vector_impl=^{EntityHold}^{EntityHold}^{E"
		"ntityHold}}}"; };
// std::vector<oo::Ref<OOTexture>>
template <> struct OOTypeEncoding<std::vector<oo::Ref<OOTexture>>> { static constexpr char value[] = 
		"{vector<oo::Ref<OOTexture>, std::allocator<oo::Ref<OOTexture>>>={_Vector_impl=^{Ref<OOTexture>}^{Ref"
		"<OOTexture>}^{Ref<OOTexture>}}}"; };
// id
template <> struct OOTypeEncoding<OOObjCId> { static constexpr char value[] = "@"; };
// SEL
template <> struct OOTypeEncoding<OOObjCSelector> { static constexpr char value[] = ":"; };
